const routes = {"/":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#f6efdf\">\n  <meta name=\"description\" content=\"A messy-on-purpose sticky note board for capturing, doodling, and organizing ideas.\">\n  <title>Notesguy — make a mess, find the idea</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n  <main class=\"app-shell\">\n    <aside class=\"idea-dock\" aria-label=\"Add an idea\">\n      <header class=\"brand\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">✦</span>\n        <div>\n          <p class=\"eyebrow\">Avery's brain, but visible</p>\n          <h1>notes<span>guy</span></h1>\n        </div>\n      </header>\n\n      <div class=\"scribble\" aria-hidden=\"true\"></div>\n\n      <form id=\"noteForm\" class=\"note-maker\">\n        <label for=\"noteInput\">Quick—what are you thinking?</label>\n        <textarea id=\"noteInput\" maxlength=\"240\" placeholder=\"Type the half-baked idea here…\" required></textarea>\n        <div class=\"maker-row\">\n          <div class=\"swatches\" aria-label=\"Choose note color\">\n            <button class=\"swatch is-selected\" type=\"button\" data-color=\"yellow\" aria-label=\"Yellow note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"pink\" aria-label=\"Pink note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"blue\" aria-label=\"Blue note\"></button>\n          </div>\n          <button class=\"add-note\" type=\"submit\">stick it! <span aria-hidden=\"true\">↗</span></button>\n        </div>\n      </form>\n\n      <p class=\"tiny-note\">No logins. No judgment. Saved on this device.</p>\n    </aside>\n\n    <section class=\"board-wrap\" aria-label=\"Brainstorm board\">\n      <div class=\"board-heading\">\n        <div>\n          <p class=\"kicker\">TODAY'S BIG MESS</p>\n          <h2>Make a mess. <em>Find the idea.</em></h2>\n        </div>\n        <div class=\"live-count\"><strong id=\"noteCount\">0</strong><span>ideas<br>in motion</span></div>\n      </div>\n\n      <div id=\"board\" class=\"board\">\n        <canvas id=\"doodleCanvas\" aria-label=\"Doodle layer\"></canvas>\n        <div id=\"itemsLayer\" class=\"items-layer\"></div>\n        <div id=\"emptyState\" class=\"empty-state\" hidden>\n          <span aria-hidden=\"true\">↖</span>\n          <p>Your brilliant mess<br>starts over there.</p>\n        </div>\n      </div>\n\n      <nav class=\"toolbelt\" aria-label=\"Brainstorm tools\">\n        <button id=\"doodleBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon doodle-icon\" aria-hidden=\"true\"></span>Doodle</button>\n        <button id=\"arrowBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↗</span>Add arrow</button>\n        <button id=\"tidyBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">▦</span>Tidy up</button>\n        <button id=\"undoBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↶</span>Undo</button>\n        <button id=\"clearBtn\" class=\"tool danger\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear</button>\n      </nav>\n\n      <div id=\"modeHint\" class=\"mode-hint\" role=\"status\" aria-live=\"polite\">Drag notes anywhere. Double-click one to edit.</div>\n    </section>\n  </main>\n  <script src=\"script.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/index.html":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"theme-color\" content=\"#f6efdf\">\n  <meta name=\"description\" content=\"A messy-on-purpose sticky note board for capturing, doodling, and organizing ideas.\">\n  <title>Notesguy — make a mess, find the idea</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n</head>\n<body>\n  <main class=\"app-shell\">\n    <aside class=\"idea-dock\" aria-label=\"Add an idea\">\n      <header class=\"brand\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">✦</span>\n        <div>\n          <p class=\"eyebrow\">Avery's brain, but visible</p>\n          <h1>notes<span>guy</span></h1>\n        </div>\n      </header>\n\n      <div class=\"scribble\" aria-hidden=\"true\"></div>\n\n      <form id=\"noteForm\" class=\"note-maker\">\n        <label for=\"noteInput\">Quick—what are you thinking?</label>\n        <textarea id=\"noteInput\" maxlength=\"240\" placeholder=\"Type the half-baked idea here…\" required></textarea>\n        <div class=\"maker-row\">\n          <div class=\"swatches\" aria-label=\"Choose note color\">\n            <button class=\"swatch is-selected\" type=\"button\" data-color=\"yellow\" aria-label=\"Yellow note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"pink\" aria-label=\"Pink note\"></button>\n            <button class=\"swatch\" type=\"button\" data-color=\"blue\" aria-label=\"Blue note\"></button>\n          </div>\n          <button class=\"add-note\" type=\"submit\">stick it! <span aria-hidden=\"true\">↗</span></button>\n        </div>\n      </form>\n\n      <p class=\"tiny-note\">No logins. No judgment. Saved on this device.</p>\n    </aside>\n\n    <section class=\"board-wrap\" aria-label=\"Brainstorm board\">\n      <div class=\"board-heading\">\n        <div>\n          <p class=\"kicker\">TODAY'S BIG MESS</p>\n          <h2>Make a mess. <em>Find the idea.</em></h2>\n        </div>\n        <div class=\"live-count\"><strong id=\"noteCount\">0</strong><span>ideas<br>in motion</span></div>\n      </div>\n\n      <div id=\"board\" class=\"board\">\n        <canvas id=\"doodleCanvas\" aria-label=\"Doodle layer\"></canvas>\n        <div id=\"itemsLayer\" class=\"items-layer\"></div>\n        <div id=\"emptyState\" class=\"empty-state\" hidden>\n          <span aria-hidden=\"true\">↖</span>\n          <p>Your brilliant mess<br>starts over there.</p>\n        </div>\n      </div>\n\n      <nav class=\"toolbelt\" aria-label=\"Brainstorm tools\">\n        <button id=\"doodleBtn\" class=\"tool\" type=\"button\" aria-pressed=\"false\"><span class=\"tool-icon doodle-icon\" aria-hidden=\"true\"></span>Doodle</button>\n        <button id=\"arrowBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↗</span>Add arrow</button>\n        <button id=\"tidyBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">▦</span>Tidy up</button>\n        <button id=\"undoBtn\" class=\"tool\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">↶</span>Undo</button>\n        <button id=\"clearBtn\" class=\"tool danger\" type=\"button\"><span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear</button>\n      </nav>\n\n      <div id=\"modeHint\" class=\"mode-hint\" role=\"status\" aria-live=\"polite\">Drag notes anywhere. Double-click one to edit.</div>\n    </section>\n  </main>\n  <script src=\"script.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root {\n  --ink: #202020;\n  --paper: #f4ecdd;\n  --board: #fbf8ef;\n  --red: #f05a49;\n  --yellow: #f8df66;\n  --pink: #f4a6b9;\n  --blue: #9ed8e8;\n  --shadow: 5px 7px 0 rgba(32, 32, 32, .14);\n}\n\n* { box-sizing: border-box; }\n\nhtml, body { margin: 0; height: 100%; overflow: hidden; }\n\nbody {\n  color: var(--ink);\n  background: var(--paper);\n  font-family: Arial, Helvetica, sans-serif;\n}\n\nbutton, textarea { font: inherit; }\nbutton { color: inherit; }\n\n.app-shell {\n  display: grid;\n  grid-template-columns: minmax(260px, 22vw) 1fr;\n  height: 100dvh;\n  padding: 14px;\n  gap: 14px;\n}\n\n.idea-dock {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  padding: clamp(18px, 2.4vw, 34px);\n  border: 2px solid var(--ink);\n  border-radius: 8px 24px 8px 8px;\n  background: #f7f0df;\n  overflow: hidden;\n}\n\n.idea-dock::before {\n  content: \"\";\n  position: absolute;\n  width: 105px;\n  height: 24px;\n  top: -8px;\n  left: 50%;\n  transform: translateX(-50%) rotate(-2deg);\n  background: rgba(255,255,255,.48);\n  border: 1px solid rgba(32,32,32,.12);\n}\n\n.brand { display: flex; align-items: center; gap: 10px; }\n.brand-mark {\n  display: grid;\n  width: 36px;\n  height: 36px;\n  place-items: center;\n  border-radius: 50%;\n  background: var(--red);\n  font-size: 22px;\n  transform: rotate(-9deg);\n}\n.eyebrow, .kicker {\n  margin: 0 0 2px;\n  font-size: 10px;\n  font-weight: 900;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.brand h1 {\n  margin: 0;\n  font: 900 clamp(25px, 3vw, 40px)/.88 Georgia, serif;\n  letter-spacing: -.06em;\n}\n.brand h1 span { color: var(--red); font-style: italic; }\n\n.scribble {\n  width: 86%;\n  height: 28px;\n  margin: clamp(20px, 4vh, 52px) auto 8px;\n  border-top: 3px solid var(--ink);\n  border-radius: 50%;\n  transform: rotate(-2deg);\n  opacity: .8;\n}\n.scribble::after {\n  content: \"\";\n  display: block;\n  width: 70%;\n  height: 18px;\n  margin: -12px auto 0;\n  border-bottom: 2px solid var(--red);\n  border-radius: 50%;\n  transform: rotate(4deg);\n}\n\n.note-maker { margin-top: auto; margin-bottom: auto; }\n.note-maker label {\n  display: block;\n  margin-bottom: 12px;\n  font: 700 clamp(17px, 1.5vw, 23px)/1.05 \"Comic Sans MS\", \"Segoe Print\", cursive;\n  transform: rotate(-1deg);\n}\n.note-maker textarea {\n  width: 100%;\n  height: clamp(120px, 24vh, 210px);\n  padding: 18px;\n  resize: none;\n  color: var(--ink);\n  border: 2px solid var(--ink);\n  border-radius: 3px;\n  outline: none;\n  background: var(--yellow);\n  box-shadow: var(--shadow);\n  font: 600 16px/1.4 \"Comic Sans MS\", \"Segoe Print\", cursive;\n  transform: rotate(-.6deg);\n  transition: transform .2s, box-shadow .2s, background .2s;\n}\n.note-maker textarea:focus { transform: rotate(0) translateY(-2px); box-shadow: 7px 9px 0 rgba(32,32,32,.18); }\n.note-maker textarea::placeholder { color: rgba(32,32,32,.53); }\n.maker-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 15px; }\n.swatches { display: flex; gap: 7px; }\n.swatch {\n  width: 22px;\n  height: 22px;\n  padding: 0;\n  border: 1px solid var(--ink);\n  border-radius: 50%;\n  cursor: pointer;\n}\n.swatch[data-color=\"yellow\"] { background: var(--yellow); }\n.swatch[data-color=\"pink\"] { background: var(--pink); }\n.swatch[data-color=\"blue\"] { background: var(--blue); }\n.swatch.is-selected { outline: 2px solid var(--ink); outline-offset: 3px; }\n.add-note {\n  padding: 11px 17px;\n  border: 2px solid var(--ink);\n  border-radius: 999px;\n  background: var(--red);\n  box-shadow: 3px 3px 0 var(--ink);\n  font-weight: 900;\n  cursor: pointer;\n  transition: transform .12s, box-shadow .12s;\n}\n.add-note:hover { transform: translate(-1px,-1px) rotate(-1deg); box-shadow: 5px 5px 0 var(--ink); }\n.add-note:active { transform: translate(2px,2px); box-shadow: 1px 1px 0 var(--ink); }\n.tiny-note { margin: 0; font-size: 10px; font-weight: 700; opacity: .58; text-align: center; }\n\n.board-wrap {\n  position: relative;\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n  min-width: 0;\n  min-height: 0;\n  padding: clamp(16px, 2.2vw, 30px) clamp(16px, 2.6vw, 38px) 18px;\n  border: 2px solid var(--ink);\n  border-radius: 22px 7px 22px 7px;\n  background-color: var(--board);\n  background-image: radial-gradient(rgba(32,32,32,.105) .75px, transparent .75px);\n  background-size: 15px 15px;\n  overflow: hidden;\n}\n.board-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; z-index: 5; }\n.kicker { color: var(--red); }\n.board-heading h2 {\n  margin: 2px 0 10px;\n  font: 900 clamp(22px, 3vw, 46px)/1 Georgia, serif;\n  letter-spacing: -.055em;\n}\n.board-heading h2 em { font-family: \"Comic Sans MS\", \"Segoe Print\", cursive; font-weight: 400; }\n.live-count { display: flex; align-items: center; gap: 7px; padding-top: 2px; transform: rotate(3deg); }\n.live-count strong { font: 900 32px/1 Georgia, serif; color: var(--red); }\n.live-count span { font-size: 9px; line-height: 1.05; font-weight: 900; text-transform: uppercase; }\n\n.board { position: relative; min-height: 0; overflow: hidden; touch-action: none; }\n.board::before {\n  content: \"\";\n  position: absolute;\n  inset: 8px 0 13px;\n  border: 1.5px dashed rgba(32,32,32,.16);\n  border-radius: 45% 55% 48% 52% / 3% 4% 3% 4%;\n  pointer-events: none;\n}\n.items-layer, #doodleCanvas { position: absolute; inset: 0; width: 100%; height: 100%; }\n.items-layer { z-index: 2; pointer-events: none; }\n#doodleCanvas { z-index: 3; pointer-events: none; }\n#doodleCanvas.is-active { pointer-events: auto; cursor: crosshair; }\n\n.sticky {\n  position: absolute;\n  display: flex;\n  width: clamp(132px, 15vw, 190px);\n  aspect-ratio: 1.08;\n  padding: 24px 18px 16px;\n  border: 1.5px solid var(--ink);\n  background: var(--yellow);\n  box-shadow: var(--shadow);\n  transform: rotate(var(--tilt, -2deg));\n  pointer-events: auto;\n  cursor: grab;\n  user-select: none;\n  transition: box-shadow .15s;\n}\n.sticky[data-color=\"pink\"] { background: var(--pink); }\n.sticky[data-color=\"blue\"] { background: var(--blue); }\n.sticky::before {\n  content: \"\";\n  position: absolute;\n  top: -7px;\n  left: 50%;\n  width: 58px;\n  height: 17px;\n  background: rgba(255,255,255,.53);\n  border: 1px solid rgba(32,32,32,.12);\n  transform: translateX(-50%) rotate(1deg);\n}\n.sticky.is-dragging { cursor: grabbing; box-shadow: 10px 13px 0 rgba(32,32,32,.15); z-index: 20; }\n.sticky-text {\n  width: 100%;\n  overflow: hidden;\n  outline: none;\n  font: 700 clamp(13px, 1.4vw, 18px)/1.28 \"Comic Sans MS\", \"Segoe Print\", cursive;\n  white-space: pre-wrap;\n}\n.sticky-text[contenteditable=\"true\"] { cursor: text; user-select: text; background: rgba(255,255,255,.2); }\n.delete-note {\n  position: absolute;\n  top: 5px;\n  right: 6px;\n  width: 22px;\n  height: 22px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  font-size: 19px;\n  font-weight: 900;\n  cursor: pointer;\n  opacity: 0;\n}\n.sticky:hover .delete-note, .sticky:focus-within .delete-note { opacity: .55; }\n\n.arrow-sticker {\n  position: absolute;\n  z-index: 1;\n  border: 0;\n  background: transparent;\n  color: var(--red);\n  font: 900 clamp(50px, 7vw, 90px)/1 \"Comic Sans MS\", cursive;\n  transform: rotate(var(--turn, -20deg));\n  text-shadow: 1px 1px 0 var(--ink);\n  pointer-events: auto;\n  cursor: grab;\n}\n\n.empty-state { position: absolute; inset: 22% auto auto 7%; color: rgba(32,32,32,.45); transform: rotate(-7deg); }\n.empty-state span { font: 700 55px/1 \"Comic Sans MS\", cursive; }\n.empty-state p { margin: -5px 0 0 44px; font: 700 17px/1.2 \"Comic Sans MS\", cursive; }\n\n.toolbelt {\n  z-index: 5;\n  display: flex;\n  justify-content: center;\n  gap: 7px;\n  padding-top: 8px;\n}\n.tool {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  min-height: 39px;\n  padding: 7px 13px;\n  border: 1.5px solid var(--ink);\n  border-radius: 999px;\n  background: rgba(255,255,255,.73);\n  font-size: 12px;\n  font-weight: 900;\n  cursor: pointer;\n  box-shadow: 2px 2px 0 rgba(32,32,32,.18);\n}\n.tool:hover { background: white; transform: translateY(-2px) rotate(-1deg); }\n.tool[aria-pressed=\"true\"] { color: #fff; background: var(--ink); }\n.tool:disabled { opacity: .35; cursor: not-allowed; transform: none; }\n.tool-icon { display: grid; width: 20px; height: 20px; place-items: center; font-size: 20px; line-height: 1; }\n.doodle-icon { border-bottom: 2px wavy currentColor; transform: rotate(-8deg); }\n.danger { color: #a33427; }\n.mode-hint {\n  position: absolute;\n  right: 12px;\n  bottom: 7px;\n  font: 700 9px/1 \"Comic Sans MS\", cursive;\n  opacity: .52;\n  transform: rotate(-2deg);\n}\n\n@media (max-width: 760px) {\n  .app-shell { grid-template-columns: 1fr; grid-template-rows: 190px minmax(0, 1fr); padding: 8px; gap: 8px; }\n  .idea-dock { padding: 13px 16px; display: grid; grid-template-columns: 1fr 1.65fr; grid-template-rows: auto 1fr; gap: 8px 14px; }\n  .brand { align-self: start; }\n  .eyebrow { display: none; }\n  .brand h1 { font-size: 26px; }\n  .brand-mark { width: 29px; height: 29px; font-size: 17px; }\n  .scribble, .tiny-note { display: none; }\n  .note-maker { grid-column: 1 / -1; display: grid; grid-template-columns: 1fr auto; grid-template-rows: auto 1fr; gap: 5px 9px; margin: 0; }\n  .note-maker label { grid-column: 1 / -1; margin: 0; font-size: 14px; }\n  .note-maker textarea { height: 87px; padding: 12px; }\n  .maker-row { flex-direction: column; justify-content: flex-end; margin: 0; }\n  .add-note { padding: 8px 12px; }\n  .swatch { width: 17px; height: 17px; }\n  .board-wrap { padding: 12px 10px 10px; }\n  .board-heading h2 { font-size: clamp(20px, 6vw, 30px); margin-bottom: 4px; }\n  .live-count { display: none; }\n  .toolbelt { gap: 4px; }\n  .tool { min-width: 40px; padding: 7px 9px; font-size: 0; justify-content: center; }\n  .tool-icon { font-size: 20px; }\n  .sticky { width: clamp(112px, 32vw, 145px); padding: 20px 12px 12px; }\n  .sticky-text { font-size: 13px; }\n  .mode-hint { display: none; }\n}\n\n@media (max-height: 620px) and (min-width: 761px) {\n  .app-shell { padding: 8px; gap: 8px; }\n  .idea-dock { padding: 14px 20px; }\n  .scribble { margin: 10px auto 2px; }\n  .note-maker label { font-size: 15px; margin-bottom: 7px; }\n  .note-maker textarea { height: 112px; padding: 12px; }\n  .tiny-note { display: none; }\n  .board-wrap { padding-top: 13px; }\n  .board-heading h2 { font-size: 28px; margin-bottom: 3px; }\n  .tool { min-height: 34px; padding-block: 5px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; }\n}\n","type":"text/css; charset=utf-8"},"/script.js":{"body":"(() => {\n  const board = document.querySelector('#board');\n  const layer = document.querySelector('#itemsLayer');\n  const canvas = document.querySelector('#doodleCanvas');\n  const ctx = canvas.getContext('2d');\n  const form = document.querySelector('#noteForm');\n  const input = document.querySelector('#noteInput');\n  const count = document.querySelector('#noteCount');\n  const empty = document.querySelector('#emptyState');\n  const doodleBtn = document.querySelector('#doodleBtn');\n  const arrowBtn = document.querySelector('#arrowBtn');\n  const tidyBtn = document.querySelector('#tidyBtn');\n  const undoBtn = document.querySelector('#undoBtn');\n  const clearBtn = document.querySelector('#clearBtn');\n  const hint = document.querySelector('#modeHint');\n\n  const STORAGE_KEY = 'notesguy-board-v1';\n  const palette = { yellow: '#f8df66', pink: '#f4a6b9', blue: '#9ed8e8' };\n  let selectedColor = 'yellow';\n  let state = { notes: [], arrows: [], doodle: '' };\n  let history = [];\n  let drawing = false;\n  let doodleMode = false;\n  let clearArmed = false;\n  let drag = null;\n  let resizeTimer;\n\n  const uid = () => `${Date.now()}-${Math.random().toString(16).slice(2)}`;\n  const clamp = (n, min, max) => Math.max(min, Math.min(max, n));\n  const snapshot = () => JSON.stringify(state);\n\n  function remember() {\n    history.push(snapshot());\n    if (history.length > 30) history.shift();\n    undoBtn.disabled = false;\n  }\n\n  function save() {\n    try { localStorage.setItem(STORAGE_KEY, snapshot()); } catch (_) {}\n  }\n\n  function starterState() {\n    return {\n      notes: [\n        { id: uid(), text: 'What if ideas felt more like play?', color: 'yellow', x: .08, y: .12, tilt: -4 },\n        { id: uid(), text: 'messy first.\\nuseful later.', color: 'pink', x: .39, y: .43, tilt: 3 },\n        { id: uid(), text: 'Build the weird version →', color: 'blue', x: .67, y: .16, tilt: -2 }\n      ],\n      arrows: [{ id: uid(), x: .58, y: .53, turn: -18 }],\n      doodle: ''\n    };\n  }\n\n  function load() {\n    try {\n      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));\n      if (saved && Array.isArray(saved.notes) && Array.isArray(saved.arrows)) state = saved;\n      else state = starterState();\n    } catch (_) { state = starterState(); }\n  }\n\n  function updateUI() {\n    count.textContent = state.notes.length;\n    empty.hidden = state.notes.length + state.arrows.length > 0;\n    undoBtn.disabled = history.length === 0;\n  }\n\n  function render() {\n    layer.replaceChildren();\n    state.arrows.forEach(renderArrow);\n    state.notes.forEach(renderNote);\n    updateUI();\n  }\n\n  function renderNote(note) {\n    const el = document.createElement('article');\n    el.className = 'sticky';\n    el.dataset.id = note.id;\n    el.dataset.kind = 'note';\n    el.dataset.color = note.color;\n    el.style.left = `${note.x * 100}%`;\n    el.style.top = `${note.y * 100}%`;\n    el.style.setProperty('--tilt', `${note.tilt}deg`);\n    el.innerHTML = '<button class=\"delete-note\" type=\"button\" aria-label=\"Delete note\">×</button><div class=\"sticky-text\" tabindex=\"0\"></div>';\n    const text = el.querySelector('.sticky-text');\n    text.textContent = note.text;\n    text.addEventListener('dblclick', (event) => {\n      event.stopPropagation();\n      text.contentEditable = 'true';\n      text.focus();\n      const range = document.createRange();\n      range.selectNodeContents(text);\n      range.collapse(false);\n      window.getSelection().removeAllRanges();\n      window.getSelection().addRange(range);\n    });\n    text.addEventListener('blur', () => {\n      if (text.contentEditable !== 'true') return;\n      remember();\n      note.text = text.textContent.trim() || 'untitled thought';\n      text.textContent = note.text;\n      text.contentEditable = 'false';\n      save();\n    });\n    text.addEventListener('keydown', (event) => {\n      if (event.key === 'Escape') text.blur();\n      if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') text.blur();\n    });\n    el.querySelector('.delete-note').addEventListener('pointerdown', event => event.stopPropagation());\n    el.querySelector('.delete-note').addEventListener('click', () => {\n      remember();\n      state.notes = state.notes.filter(item => item.id !== note.id);\n      render();\n      save();\n    });\n    el.addEventListener('pointerdown', startDrag);\n    layer.appendChild(el);\n  }\n\n  function renderArrow(arrow) {\n    const el = document.createElement('button');\n    el.type = 'button';\n    el.className = 'arrow-sticker';\n    el.dataset.id = arrow.id;\n    el.dataset.kind = 'arrow';\n    el.setAttribute('aria-label', 'Movable arrow. Double-click to remove.');\n    el.textContent = '↗';\n    el.style.left = `${arrow.x * 100}%`;\n    el.style.top = `${arrow.y * 100}%`;\n    el.style.setProperty('--turn', `${arrow.turn}deg`);\n    el.addEventListener('pointerdown', startDrag);\n    el.addEventListener('dblclick', () => {\n      remember();\n      state.arrows = state.arrows.filter(item => item.id !== arrow.id);\n      render();\n      save();\n    });\n    layer.appendChild(el);\n  }\n\n  function startDrag(event) {\n    if (doodleMode || event.target.closest('.delete-note') || event.target.contentEditable === 'true') return;\n    const el = event.currentTarget;\n    const item = state[el.dataset.kind === 'note' ? 'notes' : 'arrows'].find(entry => entry.id === el.dataset.id);\n    if (!item) return;\n    event.preventDefault();\n    remember();\n    const rect = el.getBoundingClientRect();\n    drag = { el, item, dx: event.clientX - rect.left, dy: event.clientY - rect.top };\n    el.classList.add('is-dragging');\n    el.setPointerCapture(event.pointerId);\n    el.addEventListener('pointermove', moveDrag);\n    el.addEventListener('pointerup', endDrag, { once: true });\n    el.addEventListener('pointercancel', endDrag, { once: true });\n  }\n\n  function moveDrag(event) {\n    if (!drag) return;\n    const bounds = board.getBoundingClientRect();\n    const x = clamp(event.clientX - bounds.left - drag.dx, 0, bounds.width - drag.el.offsetWidth);\n    const y = clamp(event.clientY - bounds.top - drag.dy, 0, bounds.height - drag.el.offsetHeight);\n    drag.item.x = x / bounds.width;\n    drag.item.y = y / bounds.height;\n    drag.el.style.left = `${drag.item.x * 100}%`;\n    drag.el.style.top = `${drag.item.y * 100}%`;\n  }\n\n  function endDrag(event) {\n    if (!drag) return;\n    drag.el.classList.remove('is-dragging');\n    drag.el.removeEventListener('pointermove', moveDrag);\n    try { drag.el.releasePointerCapture(event.pointerId); } catch (_) {}\n    drag = null;\n    save();\n  }\n\n  function addNote(text) {\n    remember();\n    const offset = state.notes.length % 6;\n    state.notes.push({\n      id: uid(), text, color: selectedColor,\n      x: clamp(.12 + offset * .105, .02, .72),\n      y: clamp(.11 + (offset % 3) * .16, .03, .67),\n      tilt: [-4, 2, -1, 4, -3, 1][offset]\n    });\n    render();\n    save();\n  }\n\n  form.addEventListener('submit', event => {\n    event.preventDefault();\n    const text = input.value.trim();\n    if (!text) return;\n    addNote(text);\n    input.value = '';\n    input.focus();\n  });\n\n  document.querySelectorAll('.swatch').forEach(button => {\n    button.addEventListener('click', () => {\n      selectedColor = button.dataset.color;\n      document.querySelectorAll('.swatch').forEach(swatch => swatch.classList.toggle('is-selected', swatch === button));\n      input.style.background = palette[selectedColor];\n      input.focus();\n    });\n  });\n\n  arrowBtn.addEventListener('click', () => {\n    remember();\n    const n = state.arrows.length;\n    state.arrows.push({ id: uid(), x: .34 + (n % 4) * .11, y: .3 + (n % 3) * .13, turn: [-24, 12, -8, 27][n % 4] });\n    render();\n    save();\n    hint.textContent = 'Arrow added—drag it where the connection clicks.';\n  });\n\n  tidyBtn.addEventListener('click', () => {\n    if (!state.notes.length) return;\n    remember();\n    const width = board.clientWidth;\n    const cols = width < 520 ? 2 : width < 850 ? 3 : 4;\n    state.notes.forEach((note, index) => {\n      note.x = .035 + (index % cols) * (.91 / cols);\n      note.y = .05 + Math.floor(index / cols) * .34;\n      note.tilt = [-2, 1, -1, 2][index % 4];\n    });\n    render();\n    save();\n    hint.textContent = 'A little order. Still enough chaos.';\n  });\n\n  undoBtn.addEventListener('click', () => {\n    if (!history.length) return;\n    state = JSON.parse(history.pop());\n    render();\n    restoreDoodle();\n    save();\n  });\n\n  clearBtn.addEventListener('click', () => {\n    if (!clearArmed) {\n      clearArmed = true;\n      clearBtn.innerHTML = '<span class=\"tool-icon\" aria-hidden=\"true\">!</span>Sure?';\n      hint.textContent = 'Click “Sure?” once more to clear the whole board.';\n      setTimeout(() => {\n        clearArmed = false;\n        clearBtn.innerHTML = '<span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear';\n      }, 3000);\n      return;\n    }\n    remember();\n    state = { notes: [], arrows: [], doodle: '' };\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    clearArmed = false;\n    clearBtn.innerHTML = '<span class=\"tool-icon\" aria-hidden=\"true\">×</span>Clear';\n    render();\n    save();\n  });\n\n  doodleBtn.addEventListener('click', () => {\n    doodleMode = !doodleMode;\n    canvas.classList.toggle('is-active', doodleMode);\n    doodleBtn.setAttribute('aria-pressed', String(doodleMode));\n    hint.textContent = doodleMode ? 'Doodle mode: draw anywhere. Tap Doodle again when done.' : 'Drag notes anywhere. Double-click one to edit.';\n  });\n\n  function canvasPoint(event) {\n    const rect = canvas.getBoundingClientRect();\n    return { x: (event.clientX - rect.left) * canvas.width / rect.width, y: (event.clientY - rect.top) * canvas.height / rect.height };\n  }\n\n  canvas.addEventListener('pointerdown', event => {\n    if (!doodleMode) return;\n    remember();\n    drawing = true;\n    canvas.setPointerCapture(event.pointerId);\n    const point = canvasPoint(event);\n    ctx.beginPath();\n    ctx.moveTo(point.x, point.y);\n  });\n  canvas.addEventListener('pointermove', event => {\n    if (!drawing) return;\n    const point = canvasPoint(event);\n    ctx.lineTo(point.x, point.y);\n    ctx.strokeStyle = '#202020';\n    ctx.lineWidth = 3 * devicePixelRatio;\n    ctx.lineCap = 'round';\n    ctx.lineJoin = 'round';\n    ctx.stroke();\n  });\n  const finishDrawing = () => {\n    if (!drawing) return;\n    drawing = false;\n    state.doodle = canvas.toDataURL('image/png');\n    save();\n  };\n  canvas.addEventListener('pointerup', finishDrawing);\n  canvas.addEventListener('pointercancel', finishDrawing);\n\n  function restoreDoodle() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    if (!state.doodle) return;\n    const image = new Image();\n    image.onload = () => ctx.drawImage(image, 0, 0, canvas.width, canvas.height);\n    image.src = state.doodle;\n  }\n\n  function sizeCanvas() {\n    const previous = state.doodle || (canvas.width ? canvas.toDataURL('image/png') : '');\n    const rect = board.getBoundingClientRect();\n    canvas.width = Math.max(1, Math.round(rect.width * devicePixelRatio));\n    canvas.height = Math.max(1, Math.round(rect.height * devicePixelRatio));\n    state.doodle = previous;\n    restoreDoodle();\n  }\n\n  window.addEventListener('resize', () => {\n    clearTimeout(resizeTimer);\n    resizeTimer = setTimeout(sizeCanvas, 120);\n  });\n\n  load();\n  render();\n  requestAnimationFrame(sizeCanvas);\n})();\n","type":"text/javascript; charset=utf-8"}};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const asset = routes[url.pathname];
    if (!asset) {
      return new Response('Not found', { status: 404 });
    }
    return new Response(request.method === 'HEAD' ? null : asset.body, {
      status: 200,
      headers: {
        'content-type': asset.type,
        'cache-control': url.pathname === '/' || url.pathname === '/index.html'
          ? 'no-cache'
          : 'public, max-age=3600',
        'x-content-type-options': 'nosniff'
      }
    });
  }
};
